cd /workspace/submission && python3 - <<'PYEOF'
p='te/algorithms/sub_algorithms/admm.py'
s=open(p).read()
old_start = s.index("    def get_X_step_bias(self) -> CPUArray:")
new_tail = '''    # --------------------------------------------------------------- state
    @property
    def Z_old(self) -> CPUArray:
        return self._Z if self._Z_old is None else self._Z_old

    @property
    def rho(self) -> float:
        return self._rho

    @property
    def alpha(self) -> float:
        return 1.0 if self._alpha is None else float(self._alpha)

    def get_X_step_bias(self) -> CPUArray:
        """Consensus target minus the scaled dual: the worker-step bias core."""
        assert self._Z is not None and self._dual_var is not None
        return self._Z - self._dual_var

    def get_Z_step_bias(self, next_X: Optional[CPUArray] = None) -> CPUArray:
        """(Over-)relaxed Z-step target ``alpha*X+(1-alpha)*z0+u0``."""
        X = self._X if next_X is None else next_X
        assert X is not None and self._Z is not None and self._dual_var is not None
        if self._alpha is None:
            return X + self._dual_var
        alpha = float(self._alpha)
        return alpha * X + (1.0 - alpha) * self._Z + self._dual_var

    def record_X_update(self, next_X: CPUArray):
        self._X = next_X

    def record_Z_update(self, next_Z: CPUArray):
        self._Z_old = cpu_array(self._Z)
        self._Z = next_Z

    def _dual_var_bias(self) -> CPUArray:
        """Primal residual driving the scaled-dual update."""
        assert self._X is not None and self._Z is not None
        if self._alpha is None:
            return self._X - self._Z
        alpha = float(self._alpha)
        return alpha * self._X + (1.0 - alpha) * self.Z_old - self._Z

    def update_dual_var(self, finalize: bool = False) -> Optional[float]:
        """u <- u0 + alpha*X + (1-alpha)*z0 - z (rho*u is the true dual)."""
        self.record_dual_update(self._dual_var + self._dual_var_bias())
        if finalize and self._dual_var.size:
            return float(np.max(np.abs(self._dual_var)))
        return None

    def record_dual_update(self, next_dual_var: CPUArray):
        if self._mode == ADMMMode.ACCELERATED or self._mode == ADMMMode.ACCELERATED_OVER_RELAXED:
            self._dual_var_old = cpu_array(self._dual_var)
        self._dual_var = next_dual_var

    def rescale_dual(self, new_rho: float) -> None:
        """Retune: keep ``rho*u`` invariant while the penalty changes."""
        old = float(self._rho)
        new = float(new_rho)
        if old != new and self._dual_var is not None:
            self._dual_var = self._dual_var * (old / new)
            self._dual_var_old = None
            self._dual_var_nesterov = cpu_zeros((self._n,))
        self._rho = new
        self._rho_start = self._rho_start

    def set_state(self, Z: CPUArray, dual_var: CPUArray, rho: float) -> None:
        self._Z = cpu_array(Z)
        self._Z_old = None
        self._dual_var = cpu_array(dual_var)
        self._dual_var_old = None
        self._rho = float(rho)
        self._iterate = 0
'''
s = s[:old_start] + new_tail
